from itertools import product
from math import exp
sigmoid=lambda x: 1/(1+exp(-x))
rows=[]
for h,v,c,r,y in product([0,1],repeat=5):
 phv=1/6 if h==v else 1/3
 pr=sigmoid(.75*h+.5*c)
 py=sigmoid(-.5+2.5*v+1.75*c)
 p=phv*.5*(pr if r else 1-pr)*(py if y else 1-py)
 rows.append((h,v,c,r,y,p))
def cond_y(**conditions):
 positions={'h':0,'v':1,'c':2,'r':3}
 eligible=[row for row in rows if all(row[positions[k]]==val for k,val in conditions.items())]
 return sum(row[-1]*row[4] for row in eligible)/sum(row[-1] for row in eligible)
for h in [0,1]:
 print(f'P(Y=1 | H={h}) = {cond_y(h=h):.6f}')
for c in [0,1]:
 for r in [0,1]:
  print(f'P(Y=1 | C={c}, R={r}) = {cond_y(c=c,r=r):.6f}')
print('Reported 74.55% accuracy on 50 images implies',.7455*50,'correct predictions.')
PY"
